//! 🎛️ Resident native slot producer authenticates and funds each original source operation.
use crate::{NativeReceiver,OriginalReceivingPrimary,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneRef,retained_clone_grant_admits}};
use semio_framework_value_retirement::retirement::RetireOwned;
use semio_framework_value_native_decoding::native_decoding;
use semio_framework_value_native_storage::NativeOwnedStorage;
/// 🎛️ Retains the exact issued original source coordinates while the caller owns its authority.
pub struct NativeSlotProducer<I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>>{identity:Option<(u64,usize,usize,usize)>,input:std::marker::PhantomData<fn(&I,T)->R>}
impl<I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>> NativeSlotProducer<I,T,R>{
 /// 🌱️ Starts with no captured source or owned payload.
 pub fn new()->Self{Self{identity:None,input:std::marker::PhantomData}}
 /// 🔎️ Observes the already funded original source coordinates.
 pub fn identity(&self)->Option<(u64,usize,usize,usize)>{self.identity}
}
/// 🧵️ Lends only the private caller-owned slots selected by the actual native receiving owner.
pub enum NativeSlotOperation<'a,'source,I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>>{Capture(RetainedCloneRef<'source,I>),Bind(RetainedCloneRef<'source,I>,&'a mut Option<RetainedCloneBinding>),Reserve(RetainedCloneRef<'source,I>,&'a mut NativeOwnedStorage<R>),Seed(RetainedCloneRef<'source,I>,&'a mut NativeOwnedStorage<R>,bool,fn(bool)->Result<R,ValueError>,Option<semio_framework_value_native_storage::NativeSeedTemplate<R>>),Publish(RetainedCloneRef<'source,I>,&'a mut R,&'a mut Option<T>),Advance(RetainedCloneRef<'source,I>,&'a mut R,usize)}
/// 🪪️ Lends the genuine original Source witness with the selected slot operation.
pub struct NativeSlotContext<'a,'source,I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>>{operation:NativeSlotOperation<'a,'source,I,T,R>,witness:semio_framework_value_control_contract::OriginalSourceTurnWitness<'source>}
impl<'a,'source,I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>> NativeSlotOperation<'a,'source,I,T,R>{pub fn with_witness(self,witness:semio_framework_value_control_contract::OriginalSourceTurnWitness<'source>)->NativeSlotContext<'a,'source,I,T,R>{NativeSlotContext{operation:self,witness}}}
impl<I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>> RetireOwned for NativeSlotProducer<I,T,R>{type RetirementCursor=<Option<(u64,usize,usize,usize)> as RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{self.identity.retirement_seed()}fn controlled_retirement_supported()->bool{<Option<(u64,usize,usize,usize)> as RetireOwned>::controlled_retirement_supported()}}impl<I:?Sized+'static,T:RetireOwned,R:NativeReceiver<I,T>> native_decoding::OriginalEffectProducer for NativeSlotProducer<I,T,R>{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=NativeSlotContext<'turn,'source,I,T,R> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{let input=match &context.operation{NativeSlotOperation::Capture(input)|NativeSlotOperation::Bind(input,_)|NativeSlotOperation::Reserve(input,_)|NativeSlotOperation::Seed(input,_,_,_,_)|NativeSlotOperation::Publish(input,_,_)|NativeSlotOperation::Advance(input,_,_)=>*input};if self.identity.is_some_and(|identity|identity!=input.reference_identity()){Err(ValueError::invariant("original native slot source changed"))}else{Ok(())}}
 fn source_turn<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{Some(context.witness.identity())}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:native_decoding::OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<native_decoding::OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{if let NativeSlotOperation::Publish(_,receiver,output)=&mut context.operation{return receiver.take(output,effect,reply)}if let NativeSlotOperation::Advance(input,receiver,body)=&mut context.operation{return receiver.advance_local(*input,*body,effect,reply)}let turn=match &mut context.operation{NativeSlotOperation::Capture(input)=>{let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<(u64,usize,usize,usize)>>(),depth:1,..Default::default()};if !retained_clone_grant_admits(effect.grant(),d)||effect.maximum_work_units()==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original source capture exceeded its work authority").into())))}self.identity=Some(input.reference_identity());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1})},NativeSlotOperation::Bind(input,binding)=>{let turn=input.bind(binding,effect);match turn.result{Ok(Some(progress))=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(progress)),work:turn.work}),Ok(None) if binding.is_some()=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:turn.work}),Ok(None)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("original source binding was not retained").into()),work:turn.work}),Err(error)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error.into()),work:turn.work})}},NativeSlotOperation::Reserve(_,owner)=>owner.reserve_empty(effect).map_err(Into::into),NativeSlotOperation::Seed(_,owner,subset,seed,template)=>match template{Some(template)=>{let turn=owner.initialize_template(*template,effect);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work})},None=>owner.initialize_seed(effect,||seed(*subset)).map_err(Into::into)},NativeSlotOperation::Publish(..)|NativeSlotOperation::Advance(..)=>unreachable!("receiver action is lent directly to its original owner")};Ok(match turn{RetainedWorkPoll::Pending{..}=>reply.pending(),RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result)})}
 fn recover<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:native_decoding::OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<native_decoding::OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{match &mut context.operation{NativeSlotOperation::Publish(_,receiver,output)=>receiver.recover_take(output,effect,reply),NativeSlotOperation::Advance(input,receiver,body)=>receiver.recover_advance_local(*input,*body,effect,reply),_=>Ok(reply.pending())}}
}
